      text-decoration: none;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 0.5rem;
      cursor: pointer;
      transition: transform 160ms ease, box-shadow 160ms ease, background-color 160ms ease, border-color 160ms ease;
    }

    .button {
      background: var(--color-text);
      color: #fff;
      box-shadow: 0 10px 26px rgba(31, 27, 23, 0.18);
    }

    .button-secondary {
      background: var(--color-surface);
      color: var(--color-text);
      border-color: var(--color-border);
    }

    .button:hover,
    .button-secondary:hover {
      transform: translateY(-1px);
    }

    .button:focus-visible,
    .button-secondary:focus-visible,
    .product-link:focus-visible,
    .primary-nav a:focus-visible,
    .cart-link:focus-visible {
      outline: 3px solid var(--color-focus);
      outline-offset: 3px;
    }

    .hero-panel {
      padding: 1rem;
      display: grid;
      gap: 1rem;
      align-content: space-between;
      background:
        linear-gradient(180deg, rgba(255, 255, 255, 0.94), rgba(255, 255, 255, 0.95)),
        radial-gradient(circle at top left, #f1c7a4 0, transparent 34%),
        radial-gradient(circle at bottom right, #bdd1c4 0, transparent 28%),
        var(--color-surface);
    }

    .hero-visual {
      min-height: 24rem;
      border-radius: calc(var(--radius-lg) - 8px);
      border: 1px solid var(--color-border);
      background:
        linear-gradient(160deg, #244f46 0%, #17302b 44%, #f4eee6 44%, #f4eee6 100%);
      color: #fff;
      padding: 1.1rem;
      display: grid;
      align-content: end;
      gap: 1rem;
      overflow: hidden;
      position: relative;
    }

    .hero-visual::before,
    .hero-visual::after {
      content: "";
      position: absolute;
      border-radius: 999px;
      filter: blur(0);
    }

    .hero-visual::before {
      width: 12rem;
      height: 12rem;
      right: -3rem;
      top: -4rem;
      background: #b95f33;
      opacity: 0.18;
    }

    .hero-visual::after {
      width: 9rem;
      height: 9rem;
      left: -2rem;
      bottom: 4rem;
      background: #fff;
      opacity: 0.18;
    }

    .hero-note {
      display: grid;
      gap: 0.45rem;
      max-width: 18rem;
      position: relative;
      z-index: 1;
    }

    .hero-note strong {
      font-size: 1.15rem;
    }

    .hero-note span {
      color: #f3e9df;
      font-size: 0.95rem;
    }

    .stats {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 0.75rem;
    }

    .stat {
      padding: 0.9rem 1rem;
      border-radius: var(--radius-md);
      background: rgba(255, 255, 255, 0.78);
      color: var(--color-text);
      border: 1px solid rgba(216, 207, 194, 0.95);
    }

    .stat strong {
      display: block;
      font-size: 1.12rem;
    }

    .stat span {
      color: var(--color-muted-text);
      font-size: 0.9rem;
    }

    .section {
      padding: 0.5rem 0 1.75rem;
    }

    .section-header {
      display: flex;
      align-items: end;
      justify-content: space-between;
      gap: 1rem;
      margin-bottom: 1rem;
    }

    .section-header p {
      color: var(--color-muted-text);
      max-width: 56ch;
    }

    .section h2 {
      font-size: clamp(1.45rem, 3vw, 2.05rem);
      letter-spacing: -0.03em;
    }

    .card-list {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 1rem;
    }

    .product-card {
      overflow: clip;
      display: grid;
      grid-template-rows: auto 1fr;
    }

    .product-visual {
      min-height: 16rem;
      background: var(--color-surface-alt);
      position: relative;
    }

    .product-visual img {
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    .badge {
      position: absolute;
      top: 1rem;
      left: 1rem;
      padding: 0.35rem 0.6rem;
      border-radius: 999px;
      background: #ffffff;
      color: var(--color-accent-strong);
      border: 1px solid var(--color-border);
      font-size: 0.78rem;
      font-weight: 700;
    }

    .product-body,
    .story-body,
    .deal-body {
      padding: 1rem;
      display: grid;
      gap: 0.75rem;
    }

    .product-meta,
    .story-meta,
    .deal-meta {
      display: flex;
      justify-content: space-between;
      gap: 0.75rem;
      align-items: center;
      color: var(--color-muted-text);
      font-size: 0.94rem;
    }

    .product-link {
      color: var(--color-text);
      text-decoration: none;
    }

    .product-link h3,
    .story-card h3,
    .deal-card h3 {
      font-size: 1.05rem;
      line-height: 1.25;
    }

    .price {
      font-weight: 800;
      color: var(--color-text);
    }

    .product-actions {
      display: flex;
      gap: 0.65rem;
      flex-wrap: wrap;
      padding-top: 0.15rem;
    }

    .small-button {
      padding: 0.7rem 1rem;
      font-size: 0.95rem;
    }

    .section-card {
      padding: 1rem;
    }

    .deal-grid {
      display: grid;
      grid-template-columns: 1.1fr 0.9fr;
      gap: 1rem;
    }

    .deal-card {
      overflow: hidden;
      display: grid;
      grid-template-columns: 0.95fr 1.05fr;
      min-height: 18rem;
    }

    .deal-card.featured {
      background:
        linear-gradient(120deg, #f8f0e5 0%, #ffffff 54%),
        var(--color-surface);
    }

    .deal-card .deal-art {
      background:
        radial-gradient(circle at 25% 30%, #b95f33 0 8%, transparent 9%),
        radial-gradient(circle at 76% 28%, #1f5d4e 0 10%, transparent 11%),
        radial-gradient(circle at 45% 70%, #d9c3ac 0 14%, transparent 15%),
        linear-gradient(160deg, #f2e2cf, #ebd6bf);
      position: relative;
    }

    .deal-card .deal-art::after {
      content: "";
      position: absolute;
      inset: auto 1.1rem 1.1rem 1.1rem;
      height: 38%;
      border-radius: 22px;
      background: linear-gradient(180deg, rgba(255,255,255,0.86), rgba(255,255,255,0.4));
      border: 1px solid rgba(216, 207, 194, 0.95);
    }

    .deal-promo {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      width: fit-content;
      padding: 0.38rem 0.65rem;
      border-radius: 999px;
      background: #f0f7f4;
      color: var(--color-success);
      font-size: 0.8rem;
      font-weight: 700;
    }

    .deal-body p,
    .story-body p {
      color: var(--color-muted-text);
    }

    .story-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 1rem;
    }

    .story-card {
      overflow: hidden;
      display: grid;
      grid-template-rows: auto 1fr;
    }

    .story-card img {
      aspect-ratio: 16 / 10;
      object-fit: cover;
    }

    .story-card a {
      color: inherit;
    }

    .story-card .kicker {
      color: var(--color-accent-strong);
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      font-size: 0.75rem;
    }

    .footer {
      padding: 1rem 0 2rem;
      color: var(--color-muted-text);
    }

    .footer-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      border-top: 1px solid var(--color-border);
      padding-top: 1rem;
      flex-wrap: wrap;
    }

    .footer-nav ul {
      display: flex;
      gap: 1rem;
      flex-wrap: wrap;
    }

    .footer-nav a {
      color: inherit;
      text-decoration: none;
    }

    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }

    .status {
      min-height: 1.5rem;
      color: var(--color-success);
      font-weight: 600;
    }

    svg {
      fill: currentColor;
      stroke: currentColor;
    }

    @media (max-width: 1080px) {
      .hero,
      .deal-grid {
        grid-template-columns: 1fr;
      }

      .card-list,
      .story-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }
    }

    @media (max-width: 720px) {
      .topbar,
      .section-header,
      .footer-inner {
        align-items: start;
        flex-direction: column;
      }

      .primary-nav ul {
        gap: 0.6rem 1rem;
      }

      .card-list,
      .story-grid,
      .stats,
      .deal-card {
        grid-template-columns: 1fr;
      }

      .hero-copy,
      .hero-panel,
      .section-card {
        border-radius: 24px;
      }

      .hero-visual {
        min-height: 20rem;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      html {
        scroll-behavior: auto;
      }

      *,
      *::before,
      *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
      }
    }

    @media (prefers-reduced-motion: no-preference) {
      .product-card,
      .story-card,
      .deal-card {
        transition: transform 160ms ease, box-shadow 160ms ease;
      }

      .product-card:hover,
      .story-card:hover,
      .deal-card:hover {
        transform: translateY(-2px);
      }
    }

    @media (forced-colors: active) {
      :root {
        --color-bg: Canvas;
        --color-surface: Canvas;
        --color-surface-alt: Canvas;
        --color-text: CanvasText;
        --color-muted-text: CanvasText;
        --color-link: LinkText;
        --color-border: ButtonBorder;
        --color-focus: Highlight;
        --color-accent: Highlight;
        --color-accent-strong: Highlight;
        --color-success: CanvasText;
        --shadow: none;
      }

      body {
        background: Canvas;
      }

      .brand-mark,
      .badge,
      .deal-promo,
      .cart-count {
        forced-color-adjust: auto;
        background: ButtonFace;
        color: ButtonText;
        border: 1px solid ButtonBorder;
      }

      .hero-copy,
      .hero-panel,
      .section-card,
      .story-card,
      .deal-card,
      .product-card,
      .cart-link,
      .button,
      .button-secondary {
        border: 1px solid ButtonBorder;
        box-shadow: none;
      }

      .button {
        background: ButtonFace;
        color: ButtonText;
      }

      .button-secondary,
      .cart-link,
      .primary-nav a,
      .footer-nav a,
      .product-link {
        color: ButtonText;
      }

      .hero-visual,
      .deal-card .deal-art,
      .stat {
        background: Canvas;
        color: CanvasText;
      }
    }
  </style>
</head>
